#pragma once
#include <stdexcept>

class RingBuffer {
public:
    explicit RingBuffer(int capacity) : capacity_(capacity), size_(0), head_(0) {
        data_ = new int[capacity_];
    }

    ~RingBuffer() {
        delete[] data_;
    }

    // BUG (feature gap): throws once the buffer is full, instead of the
    // sliding-window behavior this task asks for (overwrite the oldest
    // element and keep going).
    void push(int value) {
        if (size_ == capacity_) {
            throw std::overflow_error("RingBuffer is full");
        }
        data_[(head_ + size_) % capacity_] = value;
        size_++;
    }

    // index 0 is the OLDEST element currently held, index size()-1 is the newest.
    int at(int index) const {
        if (index < 0 || index >= size_) {
            throw std::out_of_range("index out of range");
        }
        return data_[(head_ + index) % capacity_];
    }

    int size() const { return size_; }

private:
    int* data_;
    int capacity_;
    int size_;
    int head_;
};

test_setup_files.test_ring_buffer.cpp:
#include "ring_buffer.h"
#include <cassert>
#include <iostream>
#include <stdexcept>

int main() {
    // fills to capacity normally
    {
        RingBuffer rb(3);
        rb.push(1);
        rb.push(2);
        rb.push(3);
        assert(rb.size() == 3);
        assert(rb.at(0) == 1 && rb.at(1) == 2 && rb.at(2) == 3);
    }

    // pushing past capacity overwrites the OLDEST element, sliding forward,
    // and size never exceeds capacity
    {
        RingBuffer rb(3);
        rb.push(1);
        rb.push(2);
        rb.push(3);
        rb.push(4);  // evicts 1
        rb.push(5);  // evicts 2
        assert(rb.size() == 3);
        assert(rb.at(0) == 3 && rb.at(1) == 4 && rb.at(2) == 5);
    }

    // works correctly across MULTIPLE wraparounds, not just one
    {
        RingBuffer rb(2);
        for (int i = 1; i <= 7; i++) {
            rb.push(i);
        }
        // capacity 2, pushed 1..7: the last two survive
        assert(rb.at(0) == 6 && rb.at(1) == 7);
    }

    // out-of-range access still throws
    {
        RingBuffer rb(2);
        rb.push(1);
        bool threw = false;
        try {
            rb.at(1);
        } catch (const std::out_of_range&) {
            threw = true;
        }
        assert(threw);
    }

    std::cout << "PASS" << std::endl;
    return 0;
}

